// Solver part
WSGenerator.prototype.getDirection = function (startObj, endObj) {
  var dir;
  let stRow = startObj.row,
    stCol = startObj.col,
    curRow = endObj.row,
    curCol = endObj.col;

  if (curRow === stRow && curCol !== stCol) {
    if (stCol < curCol) {
      dir = 1;
    } else {
      dir = -1;
    }
  } else if (curCol === stCol && curRow !== stRow) {
    if (stRow < curRow) {
      dir = 2;
    } else {
      dir = -2;
    }
  } else if (
    curCol - stCol === curRow - stRow ||
    stCol - curCol === stRow - curRow
  ) {
    if (stRow < curRow && stCol < curCol) {
      dir = 3;
    } else if (stRow > curRow && stCol > curCol) {
      dir = -3;
    }
  } else if (
    stRow - curRow === curCol - stCol ||
    curCol - stCol === curRow - curRow
  ) {
    if (stRow < curRow && stCol > curCol) {
      dir = 4;
    } else if (stRow > curRow && stCol < curCol) {
      dir = -4;
    }
  }
  return dir ? dir : 0;
};

WSGenerator.prototype.getStringBetweenPoints = function (startBox, endBox) {
  var dir;
  dir = this.getDirection(startBox, endBox);
  return this.getStringByRowCol(startBox, endBox, dir);
};

WSGenerator.prototype.getStringByRowCol = function (startBox, endBox, dir) {
  var returnedString = "";
  var cellIds = [];
  let str = startBox.row,
    stc = startBox.col,
    enr = endBox.row,
    enc = endBox.col;

  switch (dir) {
    case -1: {
      for (let k = stc; k >= enc; k -= 1) {
        returnedString = returnedString + this.gridArr[str][k].letter;
        cellIds.push([str, k]);
      }
      break;
    }
    case 1: {
      for (let k = stc; k <= enc; k += 1) {
        returnedString = returnedString + this.gridArr[str][k].letter;
        cellIds.push([str, k]);
      }
      break;
    }
    case -2: {
      for (let k = str; k >= enr; k -= 1) {
        returnedString = returnedString + this.gridArr[k][stc].letter;
        cellIds.push([k, stc]);
      }
      break;
    }
    case 2: {
      for (let k = str; k <= enr; k += 1) {
        returnedString = returnedString + this.gridArr[k][stc].letter;
        cellIds.push([k, stc]);
      }
      break;
    }
    case -3: {
      for (let k = str, j = stc; k >= enr, j >= enc; k -= 1, j -= 1) {
        returnedString = returnedString + this.gridArr[k][j].letter;
        cellIds.push([k, j]);
      }
      break;
    }
    case 3: {
      for (let k = str, j = stc; k <= enr, j <= enc; k += 1, j += 1) {
        returnedString = returnedString + this.gridArr[k][j].letter;
        cellIds.push([k, j]);
      }
      break;
    }
    case -4: {
      for (let k = str, j = stc; k >= enr, j <= enc; k -= 1, j += 1) {
        returnedString = returnedString + this.gridArr[k][j].letter;
        cellIds.push([k, j]);
      }
      break;
    }
    case 4: {
      for (let k = str, j = stc; k <= enr, j >= enc; k += 1, j -= 1) {
        returnedString = returnedString + this.gridArr[k][j].letter;
        cellIds.push([k, j]);
      }
      break;
    }
    default: {
    }
  }
  return { str: returnedString, ids: cellIds };
};

WSGenerator.prototype.TestString = function (testStr) {
  // match the found string with the elements of the words
  var str = testStr,
    reverseStr = "",
    matched = false,
    reverseMatched = false,
    matchFound = false,
    reverseMatchFound = false;

  for (let i = 0; i <= str.length; i += 1) {
    reverseStr = str.substring(i, i + 1) + reverseStr;
  }
  matched = this.matchString(str);
  reverseMatched = this.matchString(reverseStr);

  if (matched) {
    matchFound = this.isAlreadyFound(testStr);
  }
  if (reverseMatched) {
    reverseMatchFound = this.isAlreadyFound(reverseStr);
  }
  console.log(
    str,
    reverseStr,
    matched,
    reverseMatched,
    matchFound,
    reverseMatchFound
  );

  if (str.length == 0) {
    //Not written anything in if block
  } else {
    if (!matched) {
      toast.error(`The ${str} is not matching the specified words.`, {
        position: "top-center",
        autoClose: 4000,
      });
    }
  }

  if (matched && !matchFound) {
    return { found: false, str: testStr, match: true };
  } else if (reverseMatched && !reverseMatchFound) {
    return { found: false, str: reverseStr, match: true };
  } else if (matchFound && reverseMatchFound) {
    return { found: true, match: false };
  } else {
    return { found: false, match: false };
  }
};

WSGenerator.prototype.isAlreadyFound = function (str) {
  var count,
    found = false;
  for (count = 0; count < this.alreadyFound.length; count++) {
    if (str === this.alreadyFound[count]) {
      found = true;
      break;
    }
  }
  return found;
};

WSGenerator.prototype.matchString = function (str) {
  var matched = false;
  for (let count = 0; count < this.wordList.length; count++) {
    if (str.toUpperCase() === this.wordList[count].text.toUpperCase()) {
      matched = true;
      break;
    }
  }
  return matched;
};

WSGenerator.prototype.getBoxById = function (id) {
  let [row, col] = id.split("-cell-");
  row -= 1; // subtract for 0 based index
  col -= 1; // subtract for 0 based index
  return Object.assign({}, this.gridArr[row][col], { row: row, col: col });
};

//cell.js
class Cell extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hilighted: false,
    };

    this.mouseOver = this.mouseOver.bind(this);
    this.mouseOut = this.mouseOut.bind(this);
    this.mouseUp = this.mouseUp.bind(this);
    this.touchEnd = this.touchEnd.bind(this);
  }
  mouseOver(evt) {
    this.setState({
      hilighted: true,
    });
  }

  static getDerivedStateFromProps(props, state) {
    if (state.hilighted && !props.hasSelectionStarted()) {
      return {
        hilighted: false,
      };
    }
    return null;
  }

  mouseOut(evt) {
    let id = evt.target.id;
    let startBox = this.props.hasSelectionStarted();
    let hilighted = false;
    if (startBox && startBox.id === id) {
      hilighted = true;
    }
    this.setState({
      hilighted: hilighted,
    });
  }

  mouseUp(evt) {
    let evtid = evt.target.id;
    // console.log(evtid);
    if (evtid) {
      this.props.selectionEnd(evtid); // Pass the ID to the selectionEnd function
    }
  }

  touchEnd(e) {
    // Prevent the default behavior of the touch event
    // e.preventDefault();

    // Get the touch point details from the event
    const touch = e.changedTouches[0];

    // Get the X and Y coordinates of the touch end
    const touchX = touch.clientX;
    const touchY = touch.clientY;

    // Get the element under the touch point using the coordinates
    const touchedElement = document.elementFromPoint(touchX, touchY);

    if (touchedElement) {
      // Assuming each letter has a unique `data-id` attribute
      const letterId = touchedElement.id;
      // console.log(letterId);

      if (letterId) {
        this.props.selectionEnd(letterId); // Pass the ID to the selectionEnd function
      }
    }
  }

  render() {
    let cell = this.props.cell;
    let id = cell.id;
    let currClass =
      "cell" + (cell.used || this.state.hilighted ? " hilighted" : "");

    // Apply specific styles based on whether the cell is 'correct' or 'error'
    let style = {};
    if (cell.correct) {
      style = { backgroundColor: "#11a7e1", color: "white" }; // Correct selection, blue background
    } else if (cell.error) {
      style = { backgroundColor: "red", color: "white" }; // Error selection, red background
    }
    return (
      <div
        className={currClass}
        id={id}
        style={style} // Apply the style here
        onMouseDown={this.props.selectionStart}
        onMouseUp={this.mouseUp}
        onMouseOver={this.mouseOver}
        onMouseOut={this.mouseOut}
        onTouchStart={this.props.selectionStart}
        onTouchEnd={this.touchEnd}
        onTouchMove={this.mouseOver}
      >
        {cell.letter}
      </div>
    );
  }
}

//row.js
class Row extends React.Component {
  render() {
    let row = this.props.row;
    return (
      <div>
        {row.map((item, i) => {
          return (
            <Cell
              cell={item}
              key={i}
              selectionStart={this.props.selectionStart}
              selectionEnd={this.props.selectionEnd}
              mouseOver={this.props.mouseOver}
              hasSelectionStarted={this.props.hasSelectionStarted}
            />
          );
        })}
      </div>
    );
  }
}

//grid.js
class Grid extends React.Component {
  constructor(props) {
    super(props);

    this.ws = props.ws;
    this.ws.startBox = null;
    this.ws.endBox = null;

    this.selectionStart = this.selectionStart.bind(this);
    this.selectionEnd = this.selectionEnd.bind(this);
    this.hasSelectionStarted = this.hasSelectionStarted.bind(this);
    this.state = {
      ws: this.ws,
      count: 0,
      showwordexplanation: "false",
      word: "",
    };
  }

  selectionStart(evt) {
    let id = evt.target.id;
    this.ws.startBox = this.ws.getBoxById(id);
    return false;
  }

  selectionEnd(evtid) {
    if (this.ws.startBox != null) {
      let id = evtid;
      this.ws.endBox = this.ws.getBoxById(id);
    }
    if (this.ws.startBox && this.ws.endBox) {
      let strObj = this.ws.getStringBetweenPoints(
        this.ws.startBox,
        this.ws.endBox
      );

      let str = strObj.str;
      let obj = this.ws.TestString(str);

      if (str.length == 1 || !str.length) return;

      if (obj.match && !obj.found) {
        // Word is matched but not found yet
        this.ws.alreadyFound.push(str);
        this.ws.wordList.forEach((item) => {
          if (
            item.text.toLowerCase() === str.toLowerCase() ||
            str.split("").reverse().join("").toLowerCase() ===
              item.text.toLowerCase()
          ) {
            item.found = true;
            this.setState((prevState) => ({
              count: prevState.count + 1,
            }));

            // If found, mark the cells as 'correct' and remove any 'error' flag
            strObj.ids.forEach((cellPos) => {
              let [i, j] = cellPos;
              this.ws.gridArr[i][j].correct = true; // Mark cells as correct
              this.ws.gridArr[i][j].error = false; // Remove error flag
            });

            if (this.state.count == 4) {
              let { props } = this.props;
              props.props1.apply();

              Time[2].hours = props.props2;
              Time[2].minutes = props.props3;
              Time[2].seconds = props.props4;

              toast.success("Good!", {
                position: "top-center",
                autoClose: 4000,
              });
              window.localStorage.setItem("level", 2);
            }
          }
        });
      } else if (!obj.match) {
        // Word not matched, mark cells as having an error
        strObj.ids.forEach((item) => {
          let [i, j] = item;
          this.ws.gridArr[i][j].error = true; // Set error flag
        });
      }

      this.ws.startBox = null;
      this.ws.endBox = null;
      this.setState({
        ws: this.ws,
      });
      return false;
    }
  }

  hasSelectionStarted() {
    return this.ws.startBox;
  }

  render() {
    let gridArr = this.props.ws.gridArr.slice();
    let wordList = this.props.ws.wordList.slice();
    let toastVisible =
      this.props.ws.wordList.length === this.props.ws.alreadyFound.length;
    return (
      <div className="row">
        <div className="col-auto">
          <div className="d-flex">
            {gridArr.map((row, i) => {
              return (
                <Row
                  row={row}
                  rowIndex={i}
                  key={i}
                  selectionStart={this.selectionStart}
                  selectionEnd={this.selectionEnd}
                  hasSelectionStarted={this.hasSelectionStarted}
                />
              );
            })}
          </div>
        </div>
        <div className="col-auto" id="word-list">
          <div
            style={{ display: toastVisible ? "block" : "block" }}
            className="ws-my-page-success-toast"
          >
            List of words
          </div>
          <ul>
            {wordList.map((item, i) => {
              let styleObj = {
                textDecoration: item.found ? "line-through" : "none",
                display: "flex",
                justifyContent: "space-between",
              };
              return (
                <li key={i} style={styleObj}>
                  <div>{item.text}</div>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    );
  }
}

//wordsearch.js
class WordSearch3 extends React.Component {
  constructor(props) {
    super(props);
    this.state = {};
    this.wsGenerator = new WSGenerator();
    this.wsGenerator.setGridSize();
    this.wsGenerator.initGrid();
    this.wsGenerator.populateUnusedBoxes();
  }

  render() {
    return (
      <div>
        <Grid ws={this.wsGenerator} props={this.props} />
      </div>
    );
  }
}

export default WordSearch3;
