import React from "react";
import WordSearch1 from "./WordSearch1";
import { useState } from "react";
import { useStopwatch } from "react-timer-hook";
import { Button } from "@mui/material";
import Modal from "react-bootstrap/Modal";
import gridgif from "../image/GridImg/LatestGrid.gif";
import WordSearch2 from "./WordSearch2";
import WordSearch3 from "./WordSearch3";
import WordSearch4 from "./WordSearch4";
import WordSearch5 from "./WordSearch5";
import Time from "../Time.json";
import { Table } from "react-bootstrap";
import Box from "@mui/material/Box";
import InputLabel from "@mui/material/InputLabel";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import Select from "@mui/material/Select";
import useWebSocket, { ReadyState } from "react-use-websocket";
import logconfig from "../config/dbconfig";
import { SendLogData } from "../config/wslog.js";
import ReactGA from "react-ga4";
import { useTranslation } from "react-i18next";

export const Midcontent = () => {
  const { t } = useTranslation();
  const [pageName, setpageName] = useState("mainpage");
  const { sendJsonMessage } = useWebSocket(logconfig.logurl, { share: true });

  const [flag1, setFlag1] = useState(false);
  const [flag2, setFlag2] = useState(false);
  const [flag3, setFlag3] = useState(false);
  const [flag4, setFlag4] = useState(false);
  const [flag5, setFlag5] = useState(false);

  const { seconds, minutes, hours, days, isRunning, start, pause, reset } =
    useStopwatch({ autoStart: false });

  const [help_show, help_setShow] = useState(false);
  const [summary_show, summary_setShow] = useState(false);

  const help_handleClose = () => {
    help_setShow(false);
    ReactGA.event({
      action: `Eng2|vocabulary|clicked on close button of help popup`,
      category: `Eng2|clicked on close button`,
      label: `Eng2|clicked on close button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "close",
      "click",
      "help popup will be close",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };
  const help_handleShow = () => {
    help_setShow(true);
    ReactGA.event({
      action: `Eng2|vocabulary|clicked on help button`,
      category: `Eng2|clicked on help button`,
      label: `Eng2|clicked on help button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "help",
      "click",
      "help popup will be shown",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "Help popup",
          popuptext: "help",
        },
      ],
      [{ hint: "" }]
    );
  };

  const summary_handleShow = () => {
    summary_setShow(true);

    ReactGA.event({
      action: `Eng2|vocabulary|clicked on summary button`,
      category: `Eng2|clicked on summary button`,
      label: `Eng2|clicked on summary button`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "clicked",
      "select",
      "selected option decodes the wordlist",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  const summary_handleClose = () => {
    summary_setShow(false);
    ReactGA.event({
      action: `Eng2|vocabulary|clicked on close button of summary pop up`,
      category: `Eng2|clicked on close button of summary pop up`,
      label: `Eng2|clicked on close button of summary pop up`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "close",
      "clicked",
      "close button is used to close the summary.",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "",
          popuptext: "",
        },
      ],
      [{ hint: "" }]
    );
  };

  function handleDropdownChange(event) {
    // console.log(event.target.value);
    ReactGA.event({
      action: `Eng2|vocabulary|select ${event.target.value}`,
      category: `Eng2|select ${event.target.value}`,
      label: `Eng2|select ${event.target.value}`,
    });

    SendLogData(
      sendJsonMessage,
      pageName,
      "summary",
      "clicked",
      "popup showing the time taken to complete the grid for each catagory",
      [{ input: "", answer: "", result: "" }],
      [
        {
          popuptype: "summary popup",
          popuptext: "summary",
        },
      ],
      [{ hint: "" }]
    );

    if (event.target.value == "School") {
      reset.apply();
      setFlag1(true);
      setFlag2(false);
      setFlag3(false);
      setFlag4(false);
      setFlag5(false);
      start.apply();
    } else if (event.target.value == "Sport") {
      reset.apply();
      setFlag2(true);
      setFlag3(false);
      setFlag1(false);
      setFlag4(false);
      setFlag5(false);
      start.apply();
    } else if (event.target.value == "Environment") {
      reset.apply();
      setFlag3(true);
      setFlag1(false);
      setFlag2(false);
      setFlag4(false);
      setFlag5(false);
      start.apply();
    } else if (event.target.value == "Family") {
      reset.apply();
      setFlag3(false);
      setFlag1(false);
      setFlag2(false);
      setFlag4(true);
      setFlag5(false);
      start.apply();
    } else if (event.target.value == "Travel") {
      reset.apply();
      setFlag3(false);
      setFlag1(false);
      setFlag2(false);
      setFlag4(false);
      setFlag5(true);
      start.apply();
    }
  }

  return (
    <div
      className="scrollbar-primary row d-flex"
      style={{
        width: "100vw",
        backgroundColor: "#F2FBFF",
        borderRadius: "14px",
        opacity: 1,
        boxShadow: "0px 10px 5px rgba(0, 0, 0, 0.40)",
        display: "block",
        overflow: "auto",
      }}
    >
      <div className="col-sm-9 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            padding: "4%",
            paddingTop: "0%",
            overflow: "auto",
            margin: "5px",
          }}
        >
          <div className=" row mb-3 sticky-top align-items-center">
            <div className="col m-1">
              <Box sx={{ minWidth: 200 }}>
                <FormControl fullWidth size="small">
                  <InputLabel id="demo-simple-select-label">
                    Select catagory
                  </InputLabel>
                  <Select
                    label="Select catagory"
                    onChange={handleDropdownChange}
                  >
                    <MenuItem value="School">School</MenuItem>
                    <MenuItem value="Sport">Sport</MenuItem>
                    <MenuItem value="Environment">Environment</MenuItem>
                    <MenuItem value="Family">Family</MenuItem>
                    <MenuItem value="Travel">Travel</MenuItem>
                  </Select>
                </FormControl>
              </Box>
            </div>

            <div className="col text-center me-1">
              <Button
                variant="contained"
                onClick={help_handleShow}
                color="success"
              >
                {t("help")}
              </Button>
            </div>
            <Modal show={help_show} onHide={help_handleClose}>
              <Modal.Header closeButton className="bg-info">
                <Modal.Title>
                  <b>{t("help")}</b>
                </Modal.Title>
              </Modal.Header>
              <Modal.Body>
                <img className="img-fluid" src={gridgif} alt="logo" />
              </Modal.Body>
              <Modal.Footer>
                <Button
                  variant="contained"
                  color="error"
                  onClick={help_handleClose}
                >
                  {t("close")}
                </Button>
              </Modal.Footer>
            </Modal>
            <div className="col text-center">
              <Button
                variant="contained"
                onClick={summary_handleShow}
                color="success"
              >
                {t("summary")}
              </Button>
            </div>
            <Modal show={summary_show} onHide={summary_handleClose}>
              <Modal.Header closeButton className="bg-info">
                <Modal.Title>
                  <b>{t("summary")}</b>
                </Modal.Title>
              </Modal.Header>
              <Modal.Body>
                <div>
                  <Table striped bordered hover size="sm">
                    <thead className="text-center">
                      <tr>
                        <th>Catagory</th>
                        <th>Time Taken</th>
                      </tr>
                    </thead>
                    <tbody className="text-center">
                      <tr>
                        <td>School</td>
                        <td>
                          <span>
                            <span>{Time[0].minutes}</span>&nbsp;:&nbsp;
                            <span>{Time[0].seconds}</span>&nbsp;min
                          </span>
                        </td>
                      </tr>
                      <tr>
                        <td>Sport</td>
                        <td>
                          <span>
                            <span>{Time[1].minutes}</span>&nbsp;:&nbsp;
                            <span>{Time[1].seconds}</span>&nbsp;min
                          </span>
                        </td>
                      </tr>
                      <tr>
                        <td>Environment</td>
                        <td>
                          <span>
                            <span>{Time[2].minutes}</span>&nbsp;:&nbsp;
                            <span>{Time[2].seconds}</span>&nbsp;min
                          </span>
                        </td>
                      </tr>
                      <tr>
                        <td>Family</td>
                        <td>
                          <span>
                            <span>{Time[3].minutes}</span>&nbsp;:&nbsp;
                            <span>{Time[3].seconds}</span>&nbsp;min
                          </span>
                        </td>
                      </tr>
                      <tr>
                        <td>Travel</td>
                        <td>
                          <span>
                            <span>{Time[4].minutes}</span>&nbsp;:&nbsp;
                            <span>{Time[4].seconds}</span>&nbsp;min
                          </span>
                        </td>
                      </tr>
                    </tbody>
                  </Table>
                  <div className="text-danger">Try to be faster!</div>
                </div>
              </Modal.Body>
              <Modal.Footer>
                <Button
                  variant="contained"
                  color="error"
                  onClick={summary_handleClose}
                >
                  {t("close")}
                </Button>
              </Modal.Footer>
            </Modal>
            <div className="col d-flex justify-content-center">
              <div id="timer">
                <span>{hours}</span>:<span>{minutes}</span>:
                <span>{seconds}</span>
              </div>
            </div>
          </div>
          <div className="centeralignment">
            {flag1 && (
              <WordSearch1
                props1={pause}
                props2={hours}
                props3={minutes}
                props4={seconds}
              />
            )}
            {flag2 && (
              <WordSearch2
                props1={pause}
                props2={hours}
                props3={minutes}
                props4={seconds}
              />
            )}
            {flag3 && (
              <WordSearch3
                props1={pause}
                props2={hours}
                props3={minutes}
                props4={seconds}
              />
            )}
            {flag4 && (
              <WordSearch4
                props1={pause}
                props2={hours}
                props3={minutes}
                props4={seconds}
              />
            )}
            {flag5 && (
              <WordSearch5
                props1={pause}
                props2={hours}
                props3={minutes}
                props4={seconds}
              />
            )}
          </div>
        </div>
      </div>

      <div className="col-sm-3 d-flex align-items-center justify-content-center">
        <div
          className="scrollbar-primary"
          style={{
            height: "80vh",
            width: "95%",
            overflow: "auto",
            overflowX: "hidden",
            borderRadius: "13px",
            boxShadow: "0px 4px 7px #00000029",
            display: "block",
            background: "#FFFFFF 0% 0% no-repeat padding-box",
            margin: "5px",
          }}
        >
          <div
            className="sticky-top text-center subheading"
            style={{
              background: "#002F65",
              borderRadius: "13px 13px 0px 0px",
              opacity: "1",
              color: "#FFFFFF",
              fontSize: "calc(1rem + 0.2vw)",
              fontWeight: "bolder",
            }}
          >
            {t("instr")}
          </div>
          <div style={{ maxHeight: "50vh", padding: "2%", lineHeight: "30px" }}>
            <div>
              {!flag1 && !flag2 && !flag3 && !flag4 && !flag5 ? (
                <ul>
                  <li>{t("instr1")}</li>
                  <li>{t("instr2")}</li>
                  <li>{t("instr3")}</li>
                </ul>
              ) : (
                <ul>
                  <li>{t("instr4")}</li>
                  <li>{t("instr5")}</li>
                  <li>{t("instr6")}</li>
                  <li>{t("instr7")}</li>
                </ul>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
