import { Route, Routes, useParams } from "react-router-dom";
import Homepage from "./component/Homepage";
import TheoryPage from "./component/TheoryPage";
import MathsQuiz from "./quiz/MathsQuiz";
import { useEffect, useState } from "react";
import ReactGA from "react-ga4";
import useWebSocket from "react-use-websocket";
import logconfig from "./config/dbconfig";
import { v4 as uuid } from "uuid";
import axios from "axios";
import SelectLevel from "./component/MainPage";
import Procedure from "./component/Procedure";
import AnimationPage from "./component/AnimationPage";
import Language from "./Language";
import { useTranslation } from "react-i18next";
import { useDispatch, useSelector } from "react-redux";
import setLangStore, { changeLang } from "./store/Store";

function App() {
  const { id } = useParams();
  const [ip, setIP] = useState("");
  let dispatch = useDispatch();
  const sid = uuid();
  const { t, i18n } = useTranslation();

  useEffect(() => {
    localStorage.setItem("sessionid", sid);
  }, []);

  useEffect(() => {
    // to call get data function which return ip address
    getData();
  }, [ip]);

  const getData = async () => {
    // const res = await axios.get("https://api.ipify.org/?format=json");
    // const res = await axios.get("https://ipapi.co/json/");
    //console.log(res.data);
    // setIP(res.data.ip);
    localStorage.setItem("clientip", ip);
  };

  const { sendJsonMessage, readyState } = useWebSocket(logconfig.logurl, {
    onOpen: () => {
      console.log("WebSocket connection established.");
    },
    onError: () => {
      console.log("WebSocket connection Error");
    },
    share: true,
    filter: () => false,
    retryOnError: true,
    shouldReconnect: () => true,
  });

  useEffect(() => {
    ReactGA.initialize("G-ZLKNSX7SDM", {
      gaOptions: {
        gtag: true,
      },
    });
  }, []);

  useEffect(() => {
    if (id == "en") {
      alert("in app en : ", id);
      i18n.changeLanguage("en");
      dispatch(changeLang("en"));
    }
    if (id == "hn") {
      alert("in app hn : ", id);
      i18n.changeLanguage("hn");
      dispatch(changeLang("hn"));
    }
  }, []);

  return (
    <Routes>
      <Route path="/:id" element={<App />} />
      <Route exact path="/" element={<Homepage />} />
      <Route exact path="/letusverify" element={<Homepage />} />
      <Route
        exact
        path="/launchpage/englishactivity"
        element={<SelectLevel />}
      />
      <Route exact path="/theory" element={<TheoryPage />} />
      <Route exact path="/procedure" element={<Procedure />} />
      <Route exact path="/quiz" element={<MathsQuiz />} />
      <Route exact path="/animation" element={<AnimationPage />}></Route>
    </Routes>
  );
}

export default App;
